package com.nextrade.common.util; import java.math.*; public final class DecimalMath { private DecimalMath(){} public static BigDecimal money(BigDecimal v){return v.setScale(4,RoundingMode.HALF_EVEN);} public static BigDecimal price(BigDecimal v,BigDecimal tick){return v.divide(tick,0,RoundingMode.HALF_EVEN).multiply(tick);} public static BigDecimal percent(BigDecimal base,BigDecimal pct){return base.multiply(pct).divide(BigDecimal.valueOf(100),8,RoundingMode.HALF_EVEN);} public static BigDecimal clamp(BigDecimal v,BigDecimal lo,BigDecimal hi){return v.max(lo).min(hi);} }